def parse_score(s):
    a, b = s.split("-")
    return (int(a), int(b))

def count_unique_tags(s):
    tags = [t.strip() for t in s.split(",")]
    return len(set(tags))

def parse_version_tuple(s):
    if s.startswith("v"):
        s = s[1:]
    major, minor, patch = s.split(".")
    return (int(major), int(minor), int(patch))

def parse_multiline_kv(s):
    if s == "":
        return {}
    result = {}
    for line in s.split("\n"):
        k, v = line.split(": ", 1)
        result[k] = v
    return result

def parse_env_line(line):
    k, v = line.split("=", 1)
    if len(v) >= 2 and v[0] == v[-1] and v[0] in ("\"", "'"):
        v = v[1:-1]
    return (k, v)

def format_duration_minutes(total_minutes):
    if total_minutes == 0:
        return "0m"
    h = total_minutes // 60
    m = total_minutes % 60
    result = ""
    if h > 0:
        result += f"{h}h"
    if m > 0:
        result += f"{m}m"
    return result

def parse_list_range_spec(spec):
    result = set()
    for token in spec.split(","):
        if "-" in token:
            a, b = token.split("-")
            result.update(range(int(a), int(b) + 1))
        else:
            result.add(int(token))
    return sorted(result)

def bank_balance_overdraft(events, overdraft_limit):
    balance = 0
    for op, amount in events:
        if op == "deposit":
            balance += amount
        elif op == "withdraw":
            if balance - amount >= -overdraft_limit:
                balance -= amount
    return balance

def inventory_counts(events):
    counts = {}
    for item, delta in events:
        if item not in counts:
            counts[item] = 0
        new_count = counts[item] + delta
        if new_count >= 0:
            counts[item] = new_count
    return counts

def elevator_floor(start_floor, commands, min_floor, max_floor):
    floor = start_floor
    for cmd in commands:
        if cmd == "UP":
            if floor < max_floor:
                floor += 1
        elif cmd == "DOWN":
            if floor > min_floor:
                floor -= 1
    return floor

def traffic_light_state(n_ticks, durations):
    red, green, yellow = durations
    cycle = red + green + yellow
    t = n_ticks % cycle
    if t < red:
        return "RED"
    elif t < red + green:
        return "GREEN"
    else:
        return "YELLOW"

def queue_simulation(commands):
    from collections import deque
    q = deque()
    for cmd in commands:
        if cmd[0] == "enqueue":
            q.append(cmd[1])
        elif cmd[0] == "dequeue":
            if q:
                q.popleft()
    return list(q)
